/* htmx.org 1.9.12 vendored stub - minimal for dashboard - CSP friendly */
var htmx=htmx||{};htmx.version="1.9.12";htmx.config=htmx.config||{timeout:7000};htmx.process=function(el){return el};
(function(){
function fire(name, target, detail){
  try{
    var ev=new CustomEvent(name,{bubbles:true, cancelable:true, detail:detail});
    (target||document).dispatchEvent(ev);
    document.dispatchEvent(ev);
  }catch(e){}
}
function swapContent(el, html, swap){
  if(!el) return null;
  var prev=el;
  if(swap==="outerHTML"){ el.outerHTML=html; }
  else { el.innerHTML=html; }
  var newEl = swap==="outerHTML" ? document.querySelector("#"+prev.id) || prev : el;
  return newEl;
}
function handleSwap(targetSel, html, swap, xhrInfo){
  // --- OOB support: extract [hx-swap-oob] before main swap (template preserves <tbody>) ---
  try{
    var tmpl=document.createElement('template');
    tmpl.innerHTML=html;
    var oobs=tmpl.content.querySelectorAll('[hx-swap-oob]');
    oobs.forEach(function(oob){
      var id=oob.id;
      if(!id) return;
      var target=document.getElementById(id);
      if(!target) return;
      var oobVal=oob.getAttribute('hx-swap-oob')||'true';
      var style='innerHTML';
      if(oobVal!=='true' && oobVal){
        if(oobVal.indexOf(':')!==-1) style=oobVal.split(':')[0];
        else style=oobVal;
      }
      if(style==='outerHTML'){
        target.outerHTML=oob.outerHTML.replace(/hx-swap-oob[^>]*\s?/,'');
      } else if(style==='innerHTML'){
        target.innerHTML=oob.innerHTML;
      } else {
        target.innerHTML=oob.innerHTML;
      }
      // auto-hide toast after 4s
      if(id==='toast'){
        (function(t){
          setTimeout(function(){ if(t && t.innerHTML.trim()!=='') { /* keep if user interacted */ } }, 0);
          setTimeout(function(){ if(t) t.innerHTML=''; }, 4500);
        })(target);
      }
      oob.remove();
    });
    // remaining html after OOB extraction
    var frag=document.createElement('div');
    // template.content -> div trick: move children
    var remaining='';
    tmpl.content.childNodes.forEach(function(n){
      if(n.nodeType===1) remaining+=n.outerHTML;
      else if(n.nodeType===3) remaining+=n.textContent;
    });
    if(oobs.length>0) html=remaining;
  }catch(e){}
  var el=targetSel ? document.querySelector(targetSel) : null;
  if(!el) return;
  var detail={target:el, xhr:xhrInfo||{status:200, responseText:html, statusText:"OK"}};
  if(!html || !html.trim()){
    // OOB-only response: don't clobber main target
    fire("htmx:afterSwap", el, detail);
    setTimeout(function(){ fire("htmx:afterSettle", el, detail); fire("htmx:load", el, {}); },0);
    return el;
  }
  if(swap==="outerHTML"){
    var id=el.id;
    el.outerHTML=html;
    var newEl=id?document.getElementById(id):null;
    if(newEl) detail.target=newEl;
    else {
      var tmp=document.createElement("div"); tmp.innerHTML=html;
      if(tmp.firstElementChild) detail.target=tmp.firstElementChild;
    }
  } else {
    el.innerHTML=html;
  }
  fire("htmx:afterSwap", detail.target, detail);
  setTimeout(function(){ fire("htmx:afterSettle", detail.target, detail); fire("htmx:load", detail.target, {}); },0);
  return detail.target;
}
function on(evt, attr, handler){
  document.addEventListener(evt,function(e){
    var a=e.target.closest("["+attr+"]");
    if(a){ handler(e,a); }
  });
}
on("click","hx-get",function(e, t){
  var url=t.getAttribute("hx-get"); if(!url) return;
  var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  var indicator=t.getAttribute("hx-indicator");
  if(indicator){ var ind=document.querySelector(indicator); if(ind) ind.classList.add("htmx-request"); }
  fetch(url,{headers:{"HX-Request":"true"}}).then(function(r){
    return r.text().then(function(c){
      var xhr={status:r.status, statusText:r.statusText, responseText:c};
      if(!r.ok){
        fire("htmx:responseError", document.body, {target:tar?document.querySelector(tar):t, xhr:xhr});
        if(tar && c) handleSwap(tar,c,sw,xhr);
        return;
      }
      handleSwap(tar,c,sw,xhr);
    });
  }).catch(function(err){
    fire("htmx:sendError", document.body, {target:tar?document.querySelector(tar):t, xhr:{status:0, responseText:""}});
  }).finally(function(){
    if(indicator){ var ind2=document.querySelector(indicator); if(ind2) ind2.classList.remove("htmx-request"); }
  });
  if(t.tagName!=="A") e.preventDefault();
});
on("submit","hx-post",function(e,t){
  e.preventDefault();
  var url=t.getAttribute("hx-post"); var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  var data=new FormData(t);
  fetch(url,{method:"POST",body:data,headers:{"HX-Request":"true"}}).then(function(r){return r.text().then(function(c){
    var toastMsg=r.headers.get('X-Toast');
    var oauthRequired=r.headers.get('X-OAuth-Required');
    var serverName = null;
    try { serverName = data.get('name'); } catch(e) { try { serverName = t.querySelector('#field-name').value; } catch(e2) {} }
    if(toastMsg){
      var toastEl=document.getElementById('toast');
      if(toastEl){
        var d=document.createElement('div');
        var isOAuth = oauthRequired === '1' || toastMsg.indexOf('OAuth') !== -1;
        d.className=isOAuth ? 'bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-xl shadow-sm text-sm flex items-center gap-2' : 'bg-amber-50 border border-amber-200 text-amber-900 px-4 py-3 rounded-xl shadow-sm text-sm';
        d.setAttribute('role', isOAuth ? 'status' : 'alert');
        d.textContent=toastMsg;
        toastEl.innerHTML='';
        toastEl.appendChild(d);
        setTimeout(function(){ if(toastEl.contains(d)) toastEl.removeChild(d); }, isOAuth ? 8000 : 4500);
      }
    } else if(oauthRequired === '1'){
      var toastEl2=document.getElementById('toast');
      if(toastEl2){
        var d2=document.createElement('div');
        d2.className='bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-xl shadow-sm text-sm';
        d2.setAttribute('role','status');
        d2.textContent='OAuth flow started — check browser';
        toastEl2.innerHTML='';
        toastEl2.appendChild(d2);
        setTimeout(function(){ if(toastEl2.contains(d2)) toastEl2.removeChild(d2); }, 8000);
      }
    }
    if(oauthRequired === '1' && serverName){
      (function(name){
        var toastEl3=document.getElementById('toast');
        function showOAuthToast(msg, isError){
          if(!toastEl3) return;
          var d3=document.createElement('div');
          d3.className= isError ? 'bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-xl shadow-sm text-sm' : 'bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-xl shadow-sm text-sm flex items-center gap-2';
          d3.setAttribute('role', isError ? 'alert' : 'status');
          d3.textContent=msg;
          toastEl3.appendChild(d3);
          setTimeout(function(){ if(toastEl3.contains(d3)) toastEl3.removeChild(d3); }, 8000);
        }
        showOAuthToast('Initiating OAuth for ' + name + '...', false);
        fetch('/api/servers/' + encodeURIComponent(name) + '/oauth/start', {method:'POST', headers:{'HX-Request':'true'}})
          .then(function(r2){ return r2.json().then(function(data2){ return {status:r2.status, data:data2}; }); })
          .then(function(res){
            if(res.status === 200 && res.data.auth_url){
              showOAuthToast('Opening browser for authentication...', false);
              window.open(res.data.auth_url, '_blank');
              var attempts=0;
              var interval=setInterval(function(){
                attempts++;
                if(attempts>60){ clearInterval(interval); showOAuthToast('OAuth timed out, try Refresh', true); return; }
                fetch('/api/servers/' + encodeURIComponent(name) + '/oauth/status', {headers:{'HX-Request':'true'}})
                  .then(function(r3){ return r3.json(); })
                  .then(function(st){
                    if(st.status === 'completed'){
                      clearInterval(interval);
                      showOAuthToast('OAuth successful! Refreshing...', false);
                      var tbody=document.getElementById('server-table-body');
                      if(tbody){
                        fetch('/dashboard/servers', {headers:{'HX-Request':'true'}})
                          .then(function(r4){ return r4.text(); })
                          .then(function(html){
                            var tmp=document.createElement('template'); tmp.innerHTML=html.trim();
                            var newTbody=tmp.content.querySelector('#server-table-body');
                            if(newTbody && tbody.parentNode) tbody.parentNode.replaceChild(newTbody, tbody);
                          });
                      }
                    }
                  }).catch(function(){});
              }, 2000);
            } else {
              var errMsg = (res.data && res.data.detail) ? res.data.detail : 'OAuth failed to start';
              showOAuthToast(errMsg, true);
            }
          }).catch(function(err){
            showOAuthToast('OAuth error: ' + err, true);
          });
      })(serverName);
    }
    var xhr={status:r.status, responseText:c, statusText:r.statusText};
    if(!r.ok){ fire("htmx:responseError", document.body, {target:tar?document.querySelector(tar):t, xhr:xhr}); }
    handleSwap(tar,c,sw,xhr);
    if(r.status === 201 && t && t.tagName === 'FORM'){
      try{ t.reset(); }catch(e){}
      var sel=document.getElementById('field-type');
      if(sel) sel.dispatchEvent(new Event('change', {bubbles:true}));
      var cb=document.getElementById('field-oauth');
      if(cb){ cb.checked=false; cb.dispatchEvent(new Event('change', {bubbles:true})); }
      var hf=document.getElementById('field-headers');
      if(hf) hf.value='';
      var ef=document.getElementById('field-env');
      if(ef) ef.value='';
    }
  });}).catch(function(){ fire("htmx:sendError", document.body, {target:tar?document.querySelector(tar):t, xhr:{status:0}}); });
});
on("click","hx-delete",function(e,t){
  if(t.getAttribute("hx-confirm") && !confirm(t.getAttribute("hx-confirm"))) return;
  var url=t.getAttribute("hx-delete"); var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  fetch(url,{method:"DELETE",headers:{"HX-Request":"true"}}).then(function(r){return r.text().then(function(c){
    if(tar==="closest tr"){ var tr=t.closest("tr"); if(tr) tr.remove(); return; }
    if(c && tar) handleSwap(tar,c,sw,{status:r.status, responseText:c});
    else if(tar==="closest tr" && !c){ var tr2=t.closest("tr"); if(tr2) tr2.remove(); }
  });});
});
on("click","hx-patch",function(e,t){
  var url=t.getAttribute("hx-patch"); var vals=t.getAttribute("hx-vals"); var hdr=t.getAttribute("hx-headers");
  var body=null; try{ body=vals?JSON.parse(vals):{}; }catch(_){ body={}; }
  var headers={"HX-Request":"true"}; if(hdr) try{ Object.assign(headers, JSON.parse(hdr)); }catch(_){}
  var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  fetch(url,{method:"PATCH",headers:Object.assign({"Content-Type":"application/json"},headers),body:JSON.stringify(body)}).then(function(r){return r.text().then(function(c){
    var xhr={status:r.status, responseText:c};
    if(tar) handleSwap(tar,c,sw,xhr);
  });});
});
on("click","hx-post",function(e,t){
  if(t.tagName==="FORM") return;
  var url=t.getAttribute("hx-post"); if(!url) return;
  var tar=t.getAttribute("hx-target"); var sw=t.getAttribute("hx-swap")||"innerHTML";
  fetch(url,{method:"POST",headers:{"HX-Request":"true"}}).then(function(r){return r.text().then(function(c){
    handleSwap(tar,c,sw,{status:r.status, responseText:c});
  });});
});
function doLoad(){
  document.querySelectorAll("[hx-trigger]").forEach(function(el){
    var trig=el.getAttribute("hx-trigger")||""; if(trig.indexOf("load")===-1) return;
    var url=el.getAttribute("hx-get"); if(!url) return;
    var tar=el.getAttribute("hx-target"); var sw=el.getAttribute("hx-swap")||"innerHTML";
    fetch(url,{headers:{"HX-Request":"true"}}).then(function(r){return r.text()}).then(function(html){
      handleSwap(tar,html,sw,{status:200, responseText:html});
    });
  });
  fire("htmx:load", document.body, {});
}
if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",doLoad); else doLoad();
})();
